`timescale 1ns / 1ps
//==========================================================================
// phase4_loopback_top
//
// generic_controller_prompt.md §3 Phase 4: "top level with compile-time
// config (no link yet)... hardware test of every signal type on the
// verified loopback pairs." One sig_cell+cap_cell pair per TYPE
// (LOW/HIGH/PULSE/CLOCK/SERIAL), each wired to one output/input FMC pair,
// all configured at compile time from fpga/src/gen/nemo_cfg_pkg.sv
// (generated by tools/nemo_ctl/gen_svh.py from config/phase4_loopback_test.yaml
// -- NOT the real chip config, which has no FMC pin assignment yet).
//
// Pairs used (docs/pin_verification.md convention: output pin i = LAi_P,
// input pin i+16 = LA(i+16)_P):
//   pair 0 (test_clock)  -- the only pair with a prior CONFIRMED hardware
//                            loopback (static + 1 MHz + multimeter, all PASS)
//   pair 1 (test_pulse)  -- pin-mapped (XDC) but not yet functionally tested
//   pair 2 (test_serial) -- ditto
//   pair 3 (test_low)    -- ditto
//   pair 4 (test_high)   -- ditto
// Testing pairs 1-4 here incidentally extends CLAUDE.md §7 item 1's open
// "verify remaining 15 pairs" task, four pairs' worth.
//
// Jumper wiring needed on the HTG-FMC-SMA-LVDS board (same header convention
// as the earlier bring-up designs -- J3 for pins 0-15, J2 for 16-31, P column
// only): J3-0 to J3-16, J3-1 to J2-17, J3-2 to J2-18, J3-3 to J2-19,
// J3-4 to J2-20. All five jumpers can be in place at once; sw[2:0] picks
// which pair's status shows on the LEDs.
//
// Switches: sw[4] = RUN (held high = running, matching the existing bring-up
// designs' sw[4] convention), sw[2:0] = which pair to display (0-4; any
// other sw[3:0] value falls back to pair 0). No reset button is wired on
// this board (same as the earlier designs) -- an internal power-on counter
// generates rst_n, and a single APPLY pulse fires automatically a few
// cycles after that, once, since this is compile-time config with no link
// to ever send a new one.
//
// LEDs: LD0 = driven output level (selected pair), LD1 = captured input
// level (selected pair, after the 2-FF sync), LD2 = live match (driven vs.
// captured; for test_serial specifically, a sticky "last capture matched
// the known pattern" bit instead, since a bit-serial capture can't be
// compared level-for-level against the live output), LD3 = sticky fault
// latch (same debounce + consecutive-mismatch pattern as
// fmc_clock_loopback.sv's LD3, reused directly), LD4 = RUN status,
// LD5-7 = unused.
//==========================================================================
module phase4_loopback_top (
    input  logic        clk,        // 100 MHz ZedBoard system clock
    input  logic [4:0]  sw,
    output logic [7:0]  led,
    inout  wire  [31:0] fmc_pins
);

    // explicit nemo_cfg_pkg:: scoping below, not a wildcard import -- Icarus Verilog
    // mis-sizes wildcard-imported localparam port connections to 1 bit (confirmed
    // with a minimal repro; explicit scoping avoids it entirely, see WORKLOG).

    // ---- power-on reset (no reset button wired on this board) ----
    logic [3:0] por_cnt = 4'd0;
    logic       rst_n;
    always_ff @(posedge clk) begin
        if (por_cnt != 4'hF) por_cnt <= por_cnt + 4'd1;
    end
    assign rst_n = (por_cnt == 4'hF);

    // ---- RUN from sw[4]; single auto-APPLY once, right after reset ----
    logic run, apply;
    logic applied_once;
    logic apply_cmd;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            applied_once <= 1'b0;
            apply_cmd    <= 1'b0;
        end else begin
            apply_cmd    <= !applied_once;
            applied_once <= 1'b1;
        end
    end

    run_ctrl u_run_ctrl (
        .clk(clk), .rst_n(rst_n),
        .run_set(sw[4]), .run_clear(~sw[4]), .apply_cmd(apply_cmd),
        .run(run), .apply(apply)
    );

    // ---- which pair's status to show on the LEDs ----
    logic [2:0] sel;
    assign sel = (sw[3:0] < 4'd5) ? sw[2:0] : 3'd0;

    // ---- internal helper clock for test_serial's shift/capture strobe --
    //      NOT tied to any FMC pin. Uses falling_edge, not rising_edge: a
    //      freshly-started CLOCK's very first rising_edge fires immediately
    //      (the idle -> first-high-phase transition, right as RUN asserts),
    //      which would shift the very first bit away before anyone ever
    //      sees it presented. falling_edge can't occur before at least a
    //      half-period has elapsed, matching the real SIPO/PISO convention
    //      noted in docs/session1 (data changes on clk_sipo's FALLING edge).
    logic serial_strobe, unused_rise, unused_active, unused_done;
    sig_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .SERIAL_W(1)) u_serial_strobe_gen (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .cfg_type(3'd3 /*CLOCK*/), .cfg_idle_level(1'b0),
        .cfg_delay('0), .cfg_param_a(nemo_cfg_pkg::SERIAL_STROBE_PERIOD), .cfg_param_b(nemo_cfg_pkg::SERIAL_STROBE_HIGH),
        .cfg_cycles('0), .cfg_msb_first(1'b1), .cfg_data('0), .cfg_bits('0),
        .shift_strobe(1'b0),
        .pin_out(), .rising_edge(unused_rise), .falling_edge(serial_strobe),
        .active(unused_active), .done(unused_done)
    );

    // ---- 5 driven test pairs ----
    logic [4:0] pin_out_vec;
    logic [4:0] rising_vec, falling_vec, active_vec, done_vec;

    sig_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .SERIAL_W(1)) u_test_clock (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .cfg_type(nemo_cfg_pkg::TEST_CLOCK_TYPE), .cfg_idle_level(nemo_cfg_pkg::TEST_CLOCK_IDLE),
        .cfg_delay(nemo_cfg_pkg::TEST_CLOCK_DELAY), .cfg_param_a(nemo_cfg_pkg::TEST_CLOCK_PARAM_A), .cfg_param_b(nemo_cfg_pkg::TEST_CLOCK_PARAM_B),
        .cfg_cycles(nemo_cfg_pkg::TEST_CLOCK_CYCLES), .cfg_msb_first(nemo_cfg_pkg::TEST_CLOCK_MSB_FIRST),
        .cfg_data(nemo_cfg_pkg::TEST_CLOCK_DATA[0:0]), .cfg_bits(nemo_cfg_pkg::TEST_CLOCK_BITS),
        .shift_strobe(1'b0),
        .pin_out(pin_out_vec[0]), .rising_edge(rising_vec[0]), .falling_edge(falling_vec[0]),
        .active(active_vec[0]), .done(done_vec[0])
    );

    sig_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .SERIAL_W(1)) u_test_pulse (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .cfg_type(nemo_cfg_pkg::TEST_PULSE_TYPE), .cfg_idle_level(nemo_cfg_pkg::TEST_PULSE_IDLE),
        .cfg_delay(nemo_cfg_pkg::TEST_PULSE_DELAY), .cfg_param_a(nemo_cfg_pkg::TEST_PULSE_PARAM_A), .cfg_param_b(nemo_cfg_pkg::TEST_PULSE_PARAM_B),
        .cfg_cycles(nemo_cfg_pkg::TEST_PULSE_CYCLES), .cfg_msb_first(nemo_cfg_pkg::TEST_PULSE_MSB_FIRST),
        .cfg_data(nemo_cfg_pkg::TEST_PULSE_DATA[0:0]), .cfg_bits(nemo_cfg_pkg::TEST_PULSE_BITS),
        .shift_strobe(1'b0),
        .pin_out(pin_out_vec[1]), .rising_edge(rising_vec[1]), .falling_edge(falling_vec[1]),
        .active(active_vec[1]), .done(done_vec[1])
    );

    sig_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .SERIAL_W(16)) u_test_serial (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .cfg_type(nemo_cfg_pkg::TEST_SERIAL_TYPE), .cfg_idle_level(nemo_cfg_pkg::TEST_SERIAL_IDLE),
        .cfg_delay(nemo_cfg_pkg::TEST_SERIAL_DELAY), .cfg_param_a(nemo_cfg_pkg::TEST_SERIAL_PARAM_A), .cfg_param_b(nemo_cfg_pkg::TEST_SERIAL_PARAM_B),
        .cfg_cycles(nemo_cfg_pkg::TEST_SERIAL_CYCLES), .cfg_msb_first(nemo_cfg_pkg::TEST_SERIAL_MSB_FIRST),
        .cfg_data(nemo_cfg_pkg::TEST_SERIAL_DATA), .cfg_bits(nemo_cfg_pkg::TEST_SERIAL_BITS),
        .shift_strobe(serial_strobe),
        .pin_out(pin_out_vec[2]), .rising_edge(rising_vec[2]), .falling_edge(falling_vec[2]),
        .active(active_vec[2]), .done(done_vec[2])
    );

    sig_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .SERIAL_W(1)) u_test_low (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .cfg_type(nemo_cfg_pkg::TEST_LOW_TYPE), .cfg_idle_level(nemo_cfg_pkg::TEST_LOW_IDLE),
        .cfg_delay(nemo_cfg_pkg::TEST_LOW_DELAY), .cfg_param_a(nemo_cfg_pkg::TEST_LOW_PARAM_A), .cfg_param_b(nemo_cfg_pkg::TEST_LOW_PARAM_B),
        .cfg_cycles(nemo_cfg_pkg::TEST_LOW_CYCLES), .cfg_msb_first(nemo_cfg_pkg::TEST_LOW_MSB_FIRST),
        .cfg_data(nemo_cfg_pkg::TEST_LOW_DATA[0:0]), .cfg_bits(nemo_cfg_pkg::TEST_LOW_BITS),
        .shift_strobe(1'b0),
        .pin_out(pin_out_vec[3]), .rising_edge(rising_vec[3]), .falling_edge(falling_vec[3]),
        .active(active_vec[3]), .done(done_vec[3])
    );

    sig_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .SERIAL_W(1)) u_test_high (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .cfg_type(nemo_cfg_pkg::TEST_HIGH_TYPE), .cfg_idle_level(nemo_cfg_pkg::TEST_HIGH_IDLE),
        .cfg_delay(nemo_cfg_pkg::TEST_HIGH_DELAY), .cfg_param_a(nemo_cfg_pkg::TEST_HIGH_PARAM_A), .cfg_param_b(nemo_cfg_pkg::TEST_HIGH_PARAM_B),
        .cfg_cycles(nemo_cfg_pkg::TEST_HIGH_CYCLES), .cfg_msb_first(nemo_cfg_pkg::TEST_HIGH_MSB_FIRST),
        .cfg_data(nemo_cfg_pkg::TEST_HIGH_DATA[0:0]), .cfg_bits(nemo_cfg_pkg::TEST_HIGH_BITS),
        .shift_strobe(1'b0),
        .pin_out(pin_out_vec[4]), .rising_edge(rising_vec[4]), .falling_edge(falling_vec[4]),
        .active(active_vec[4]), .done(done_vec[4])
    );

    // ---- drive the 5 output FMC pins; tri-state the rest of that range ----
    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : g_out
            if (g < 5)
                assign fmc_pins[g] = pin_out_vec[g];
            else
                assign fmc_pins[g] = 1'bz;
        end
    endgenerate
    // input range (16-31) is never driven by the FPGA
    generate
        for (g = 16; g < 32; g = g + 1) begin : g_in_z
            assign fmc_pins[g] = 1'bz;
        end
    endgenerate

    // ---- 2-FF sync on the 5 input FMC pins, external to cap_cell per its
    //      own header comment and CLAUDE.md §8 ----
    logic [4:0] sync0, sync_in_vec;
    always_ff @(posedge clk) begin
        sync0       <= {fmc_pins[20], fmc_pins[19], fmc_pins[18], fmc_pins[17], fmc_pins[16]};
        sync_in_vec <= sync0;
    end

    logic [4:0] level_out_vec;
    logic [4:0] cap_done_vec;
    logic [15:0] capture_reg_serial;
    logic [31:0] edge_count_clock, edge_count_pulse;

    cap_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .CAP_W(1)) u_cap_clock (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .sync_in(sync_in_vec[0]),
        .cfg_mode(nemo_cfg_pkg::TEST_CLOCK_CAP_MODE), .cfg_msb_first(1'b1), .cfg_bits('0),
        .capture_strobe(1'b0),
        .level_out(level_out_vec[0]), .edge_count(edge_count_clock),
        .period_ticks(), .high_ticks(), .period_valid(),
        .capture_reg(), .done(cap_done_vec[0])
    );

    cap_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .CAP_W(1)) u_cap_pulse (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .sync_in(sync_in_vec[1]),
        .cfg_mode(nemo_cfg_pkg::TEST_PULSE_CAP_MODE), .cfg_msb_first(1'b1), .cfg_bits('0),
        .capture_strobe(1'b0),
        .level_out(level_out_vec[1]), .edge_count(edge_count_pulse),
        .period_ticks(), .high_ticks(), .period_valid(),
        .capture_reg(), .done(cap_done_vec[1])
    );

    cap_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .CAP_W(16)) u_cap_serial (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .sync_in(sync_in_vec[2]),
        .cfg_mode(nemo_cfg_pkg::TEST_SERIAL_CAP_MODE), .cfg_msb_first(nemo_cfg_pkg::TEST_SERIAL_MSB_FIRST), .cfg_bits(nemo_cfg_pkg::TEST_SERIAL_BITS),
        .capture_strobe(serial_strobe),
        .level_out(level_out_vec[2]), .edge_count(),
        .period_ticks(), .high_ticks(), .period_valid(),
        .capture_reg(capture_reg_serial), .done(cap_done_vec[2])
    );

    cap_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .CAP_W(1)) u_cap_low (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .sync_in(sync_in_vec[3]),
        .cfg_mode(nemo_cfg_pkg::TEST_LOW_CAP_MODE), .cfg_msb_first(1'b1), .cfg_bits('0),
        .capture_strobe(1'b0),
        .level_out(level_out_vec[3]), .edge_count(),
        .period_ticks(), .high_ticks(), .period_valid(),
        .capture_reg(), .done(cap_done_vec[3])
    );

    cap_cell #(.TICK_W(nemo_cfg_pkg::TICK_W), .CAP_W(1)) u_cap_high (
        .clk(clk), .rst_n(rst_n), .run(run), .apply(apply),
        .sync_in(sync_in_vec[4]),
        .cfg_mode(nemo_cfg_pkg::TEST_HIGH_CAP_MODE), .cfg_msb_first(1'b1), .cfg_bits('0),
        .capture_strobe(1'b0),
        .level_out(level_out_vec[4]), .edge_count(),
        .period_ticks(), .high_ticks(), .period_valid(),
        .capture_reg(), .done(cap_done_vec[4])
    );

    // ---- test_serial: sticky "last capture matched the known pattern" ----
    logic serial_ok;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) serial_ok <= 1'b0;
        else if (!sw[4]) serial_ok <= 1'b0;  // same sw[4]-clears convention as the earlier designs' LD3
        else if (cap_done_vec[2]) serial_ok <= (capture_reg_serial[7:0] == nemo_cfg_pkg::TEST_SERIAL_DATA[7:0]);
    end

    // ---- live match + sticky fault latch for the 4 level-comparable pairs
    //      (clock/pulse/low/high) -- same debounce + consecutive-mismatch
    //      pattern as fmc_clock_loopback.sv's LD3, reused directly. The
    //      2-cycle sync delay is imperceptible at these human/multimeter-
    //      scale rates (100 Hz / 500 ms), unlike the original 1 MHz design,
    //      so no delay-compensation chain is needed here.
    logic [4:0] match_vec;
    assign match_vec[0] = (pin_out_vec[0] == level_out_vec[0]);
    assign match_vec[1] = (pin_out_vec[1] == level_out_vec[1]);
    assign match_vec[2] = serial_ok;  // not a level compare
    assign match_vec[3] = (pin_out_vec[3] == level_out_vec[3]);
    assign match_vec[4] = (pin_out_vec[4] == level_out_vec[4]);

    localparam int SETTLE_CYCLES      = 2_000_000; // ~20 ms at 100 MHz
    localparam int MISMATCH_THRESHOLD = 16;
    logic [21:0] settle_cnt;
    logic        settled;
    logic [4:0]  mismatch_run;
    logic        fault_latch;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n || !sw[4]) begin
            settle_cnt   <= '0;
            settled      <= 1'b0;
            mismatch_run <= '0;
            fault_latch  <= 1'b0;
        end else if (!settled) begin
            if (settle_cnt == SETTLE_CYCLES[21:0]) settled <= 1'b1;
            else settle_cnt <= settle_cnt + 22'd1;
        end else if (sel == 3'd2) begin
            // test_serial's own sticky serial_ok already covers this pair;
            // don't let its non-level-compare match_vec bit feed the
            // generic mismatch counter.
            mismatch_run <= '0;
        end else if (match_vec[sel]) begin
            mismatch_run <= '0;
        end else if (mismatch_run == MISMATCH_THRESHOLD[4:0] - 5'd1) begin
            fault_latch <= 1'b1;
        end else begin
            mismatch_run <= mismatch_run + 5'd1;
        end
    end

    assign led[0]   = pin_out_vec[sel];
    assign led[1]   = level_out_vec[sel];
    assign led[2]   = match_vec[sel];
    assign led[3]   = fault_latch;
    assign led[4]   = run;
    assign led[7:5] = 3'b0;

endmodule
